CREATE TABLE "departments" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(255) UNIQUE NOT NULL,
  "is_active" boolean NOT NULL DEFAULT true,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "positions" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(255) UNIQUE NOT NULL,
  "is_active" boolean NOT NULL DEFAULT true,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "employment_statuses" (
  "id" SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(100) UNIQUE NOT NULL
);

CREATE TABLE "employment_types" (
  "id" SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "code" varchar(30) UNIQUE NOT NULL,
  "name" varchar(100) UNIQUE NOT NULL
);

CREATE TABLE "employees" (
  "id" uuid PRIMARY KEY,
  "code" varchar(4) UNIQUE NOT NULL,
  "prefix" varchar(20),
  "first_name" varchar(255) NOT NULL,
  "last_name" varchar(255) NOT NULL,
  "email" varchar(255) UNIQUE,
  "phone" varchar(30),
  "avatar_url" text,
  "line_uid" varchar(64) UNIQUE,
  "start_date" date NOT NULL,
  "department_id" integer NOT NULL,
  "position_id" integer NOT NULL,
  "employment_status_id" smallint NOT NULL,
  "employment_type_id" smallint NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "skills" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(100) UNIQUE NOT NULL,
  "is_active" boolean NOT NULL DEFAULT true
);

CREATE TABLE "employee_skills" (
  "employee_id" uuid NOT NULL,
  "skill_id" integer NOT NULL,
  "skill_level" smallint NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  PRIMARY KEY ("employee_id", "skill_id")
);

CREATE TABLE "request_statuses" (
  "code" varchar(20) PRIMARY KEY,
  "name" varchar(100) UNIQUE NOT NULL
);

CREATE TABLE "leave_types" (
  "code" varchar(30) PRIMARY KEY,
  "name" varchar(100) UNIQUE NOT NULL,
  "description" text,
  "is_active" boolean NOT NULL DEFAULT true
);

CREATE TABLE "overtime_requests" (
  "id" uuid PRIMARY KEY,
  "employee_id" uuid NOT NULL,
  "start_at" timestamptz NOT NULL,
  "end_at" timestamptz NOT NULL,
  "reason" text NOT NULL,
  "status_code" varchar(20) NOT NULL DEFAULT 'pending',
  "decided_by_employee_id" uuid,
  "decided_at" timestamptz,
  "decision_note" text,
  "cancelled_by_employee_id" uuid,
  "cancelled_at" timestamptz,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "leave_requests" (
  "id" uuid PRIMARY KEY,
  "employee_id" uuid NOT NULL,
  "leave_type_code" varchar(30) NOT NULL,
  "start_on" date NOT NULL,
  "end_on" date NOT NULL,
  "reason" text,
  "status_code" varchar(20) NOT NULL DEFAULT 'pending',
  "decided_by_employee_id" uuid,
  "decided_at" timestamptz,
  "decision_note" text,
  "cancelled_by_employee_id" uuid,
  "cancelled_at" timestamptz,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE INDEX ON "employees" ("department_id");

CREATE INDEX ON "employees" ("position_id");

CREATE INDEX ON "employees" ("employment_status_id");

CREATE INDEX ON "employees" ("employment_type_id");

CREATE INDEX ON "employee_skills" ("skill_id");

CREATE INDEX ON "overtime_requests" ("employee_id", "start_at");

CREATE INDEX ON "overtime_requests" ("status_code", "start_at");

CREATE INDEX ON "overtime_requests" ("decided_by_employee_id");

CREATE INDEX ON "leave_requests" ("employee_id", "start_on", "end_on");

CREATE INDEX ON "leave_requests" ("status_code", "start_on");

CREATE INDEX ON "leave_requests" ("leave_type_code");

CREATE INDEX ON "leave_requests" ("decided_by_employee_id");

COMMENT ON TABLE "employment_statuses" IS 'e.g. active, probation, suspended, resigned';

COMMENT ON TABLE "employment_types" IS 'e.g. full_time, part_time, contract, intern';

COMMENT ON COLUMN "employee_skills"."skill_level" IS 'Allowed values: 1-5';

COMMENT ON TABLE "request_statuses" IS 'pending, approved, rejected, cancelled';

COMMENT ON TABLE "leave_types" IS 'e.g. sick, annual, personal, unpaid';

COMMENT ON TABLE "overtime_requests" IS 'start_at must be earlier than end_at';

COMMENT ON TABLE "leave_requests" IS 'start_on <= end_on; sessions must be valid';

ALTER TABLE "employees" ADD FOREIGN KEY ("department_id") REFERENCES "departments" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "employees" ADD FOREIGN KEY ("position_id") REFERENCES "positions" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "employees" ADD FOREIGN KEY ("employment_status_id") REFERENCES "employment_statuses" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "employees" ADD FOREIGN KEY ("employment_type_id") REFERENCES "employment_types" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "employee_skills" ADD FOREIGN KEY ("employee_id") REFERENCES "employees" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "employee_skills" ADD FOREIGN KEY ("skill_id") REFERENCES "skills" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "overtime_requests" ADD FOREIGN KEY ("employee_id") REFERENCES "employees" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "overtime_requests" ADD FOREIGN KEY ("status_code") REFERENCES "request_statuses" ("code") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "overtime_requests" ADD FOREIGN KEY ("decided_by_employee_id") REFERENCES "employees" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "overtime_requests" ADD FOREIGN KEY ("cancelled_by_employee_id") REFERENCES "employees" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "leave_requests" ADD FOREIGN KEY ("employee_id") REFERENCES "employees" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "leave_requests" ADD FOREIGN KEY ("leave_type_code") REFERENCES "leave_types" ("code") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "leave_requests" ADD FOREIGN KEY ("status_code") REFERENCES "request_statuses" ("code") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "leave_requests" ADD FOREIGN KEY ("decided_by_employee_id") REFERENCES "employees" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "leave_requests" ADD FOREIGN KEY ("cancelled_by_employee_id") REFERENCES "employees" ("id") DEFERRABLE INITIALLY IMMEDIATE;
